import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.exists(file_path):
        raise ValueError("File does not exist")

    with open(file_path, 'r') as f:
        data = json.load(f)

    for req in INPUT_JSON["required"]:
        if req not in data:
            raise ValueError(f"Missing required attribute: {req}")

    for key, rules in INPUT_JSON["properties"].items():
        if key in data:
            if not isinstance(data[key], rules["type"]):
                raise ValueError(f"Type mismatch for {key}")

    if not re.match(EMAIL_REGEX, data["email"]):
        raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError(f"Attribute {attribute} not found")

    return data[attribute]

import re
import json
import os

def task_func(file_path: str, regex_pattern=r'\(.+?\)|\w') -> dict:
    results = {}

    files_to_process = []
    if os.path.isdir(file_path):
        for f in os.listdir(file_path):
            if f.endswith('.json'):
                files_to_process.append(os.path.join(file_path, f))
    elif os.path.isfile(file_path):
        files_to_process.append(file_path)

    for path in files_to_process:
        try:
            with open(path, 'r') as f:
                data = json.load(f)
                content = json.dumps(data)
                matches = re.findall(regex_pattern, content)
                results[os.path.basename(path)] = matches
        except (json.JSONDecodeError, IOError):
            continue

    return results

